export type ExposureDayType = 'weekday' | 'saturday' | 'sunday'
export type ExposureTier = 'full-day' | 'part-day'

export interface ExposureArchetype {
  id: string                 // 'weekday|Sheffield - St Pancras|full-day'
  day: ExposureDayType
  group: string
  tier: ExposureTier
  n_diagrams: number
  avg_running_min: number
  avg_dwell_min: number
  avg_span_min: number
  avg_route_km: number
  avg_speed_mph: number
}

// One representative route trace per archetype: 15-min timestamped positions,
// each flagged running (1) or dwell (0). Tuple form keeps the bundle compact:
// [minuteOfDay, lat, lon, running]
export type TracePoint = [number, number, number, 0 | 1]

